from v5_pages import reading

def add_diagrams(b,a):
    W=a['W'];M=a['MARGIN'];CW=a['CW'];T=a['TEAL'];N=a['NAVY'];U=a['MUTED'];P=a['PALE'];A=a['AQUA'];L=a['LINE'];e=a['e'];para=a['para']
    arrow=a['arrow'];link=a['link'];xs=[M,M+181,M+362];bw=150
    def box(b,x,y,w,h,title,body='',fill=P):
        c=b.c;c.setFillColor(fill);c.setStrokeColor(L);c.roundRect(x,y-h,w,h,7,fill=1,stroke=1)
        p=para(title,11,True,T,14,1);_,hh=p.wrap(w-14,1000);p.drawOn(c,x+7,y-10-hh)
        if body:
            p=para(e(body).replace('\n','<br/>'),9.3,False,a['INK'],12,1,markup=True);_,bh=p.wrap(w-18,1000)
            assert hh+17+bh<=h-4,(title,hh,bh,h)
            p.drawOn(c,x+9,y-hh-17-bh)

    b.new('Атлас: документ и границы доверия','От данных к разрешённому действию','atlas_trust')
    b.p('Содержимое файла и вывод модели остаются данными. Право на действие определяется проверенным пользователем, политикой приложения и актуальной версией операции.',10.4,space=13)
    y=b.y
    for x,t,body in zip(xs,['1. Исходный файл','2. Парсинг / OCR','3. Предложение'],['Тип, размер, источник\nВерсия и владелец','Страница, координаты\nТекст и структура','Поля по схеме\nСсылка на исходник']):box(b,x,y,bw,77,t,body,P)
    arrow(b,xs[0]+bw,y-38,xs[1],y-38);arrow(b,xs[1]+bw,y-38,xs[2],y-38)
    yy=y-124
    for x,t,body in zip(xs,['6. CRM / учёт','5. Подтверждение','4. Правила и ACL'],['Разрешённая операция\nСверка результата','Пользователь + версия\nПовторная проверка прав','Типы, смысл, источник\nПолномочия и состояние']):box(b,x,yy,bw,84,t,body,A)
    arrow(b,xs[2]+75,y-77,xs[2]+75,yy);arrow(b,xs[2],yy-42,xs[1]+bw,yy-42);arrow(b,xs[1],yy-42,xs[0]+bw,yy-42)
    b.y=yy-104;b.figures+=1
    b.callout('Три независимые проверки','Схема подтверждает форму. Бизнес-правила и исходник помогают проверить смысл. Авторизация определяет право действовать. Успех одной проверки не заменяет остальные.')
    b.table([['Ситуация','Результат'],['JSON валиден, сумма противоречива','Review с исходным значением и расхождением.'],['Документ просит вызвать другой инструмент','Текст не изменяет список разрешений.'],['После подтверждения изменились поля или права','Прежнее подтверждение больше не разрешает запись.'],['Ответ CRM потерян','Явный неизвестный исход; повторная запись не выполняется вслепую.']],[CW*.43,CW*.57],size=9.8)
    b.p('Материалы: '+link('N04')+' · '+link('N05')+' · '+link('B11'),9.3,markup=True)
    reading(b,a,'07')

    b.new('Атлас: outbox и потерянный ответ','Сценарий во времени','atlas_outbox')
    b.p('Начало: пользователь уже подтвердил допустимую версию. Схема показывает штатную отправку и один неопределённый исход; гарантии задаются контрактами и конфигурацией.',10,space=14)
    c=b.c;y=b.y;step=CW/6;centers=[M+(i+.5)*step for i in range(6)]
    for x,title in zip(centers,['API','БД + outbox','Relay','Broker','Worker','CRM']):
        c.setFillColor(A);c.setStrokeColor(L);c.roundRect(x-step/2+3,y-30,step-6,30,4,fill=1,stroke=1)
        p=para(title,9.1,True,T,align=1);_,ph=p.wrap(step-10,100);p.drawOn(c,x-step/2+5,y-8-ph)
        c.setDash(2,3);c.setStrokeColor(L);c.line(x,y-32,x,y-288);c.setDash()
    steps=[(0,1,'1. TX: данные + событие'),(2,1,'2. Прочитать'),(2,3,'3. Publish'),(3,4,'4. Доставка'),(4,5,'5. Write(key)'),(5,4,'6. Ответ потерян'),(4,5,'7. Сверить'),(4,1,'8. Результат или unknown')]
    for i,(src,dst,label) in enumerate(steps):
        yy=y-58-i*31;col=a['AMBER'] if i==5 else T
        c.setStrokeColor(col);c.setFillColor(col)
        if i==5:c.setDash(3,2)
        x1,x2=centers[src],centers[dst];c.line(x1,yy,x2,yy)
        direction=1 if x2>x1 else -1;c.line(x2,yy,x2-direction*5,yy+3);c.line(x2,yy,x2-direction*5,yy-3);c.setDash()
        lab=para(label,7.9,False,col,9.3,align=1);ww=max(abs(x2-x1)-2,70);_,ph=lab.wrap(ww,80);lab.drawOn(c,(x1+x2)/2-ww/2,yy+5)
    b.y=y-313;b.figures+=1
    b.section('Что обеспечивает outbox','Локальное бизнес-изменение и событие фиксируются одной транзакцией. Relay может опубликовать событие повторно, если не успел сохранить отметку об отправке. Потребитель должен учитывать повторную доставку.')
    b.section('Что остаётся внешнему контракту','Confirms, consumer ACK, устойчивость хранения и повторы настраиваются отдельно. Отсутствие второго бизнес-эффекта требует идемпотентного ключа или атомарной дедупликации принимающей системы; локальный флаг не заменяет её.')
    b.callout('Неизвестный исход - отдельное состояние','Сверка помогает найти выполненную запись, но обычное «проверить, затем создать» сохраняет гонку. Если результат нельзя подтвердить и повтор небезопасен, останови автоматическую запись и передай случай оператору.')
    b.p('Первоисточники: '+link('N03')+' · '+link('B10')+' · '+link('B11'),9.2,markup=True)
    reading(b,a,'14')

    b.new('Атлас: размещение модели и данные','Три варианта и общие проверки','atlas_placement')
    b.p('Сначала классифицируй поля и связи с физлицом, цель обработки и допустимые действия. Адрес сервера или название провайдера не определяют все обязанности по данным.',10.1,space=14)
    y=b.y;c=b.c;c.setFillColor(A);c.roundRect(M,y-61,CW,61,6,fill=1,stroke=0)
    p=para('Приложение клиента: минимизация данных, права, версия и журнал решений',12,True,T,align=1);_,ph=p.wrap(CW-24,100);p.drawOn(c,M+12,y-15-ph)
    yy=y-106
    info=[('Облачный сервис в РФ','Проверить выбранный продукт, регион, договор, подрядчиков, хранение запросов и ответов.'),('Собственное размещение','Проверить сервер, лицензии, доступы, телеметрию, резервные копии, обновления и внешние вызовы.'),('Внешний сервис за рубежом','Проверить допустимость передачи, применимые требования и фактический результат обезличивания.')]
    for x,(title,body) in zip(xs,info):
        arrow(b,x+75,y-61,x+75,yy);box(b,x,yy,bw,138,title,body,P)
    b.y=yy-158;b.figures+=1
    b.table([['Проверка для любого варианта','Что записать'],['Полный путь данных','Запрос, ответ, logs, traces, кеш, файлы, embeddings, backups, сервисы и подрядчики.'],['Цель и основания','Кто оператор и обработчик, какие действия допустимы, какие документы и согласования нужны.'],['География и доступ','Конкретные конечные точки и регионы; кто имеет доступ и какие сетевые выходы разрешены.'],['Хранение и прекращение обработки','Основание, срок, производные копии и восстановление; иные законные основания проверяются отдельно.'],['Изменение провайдера','Повторить capability/eval и проверку пути данных перед переключением.']],[CW*.37,CW*.63],size=9.4,pad=5)
    b.p('Учебное архитектурное упражнение: применимые требования и действующую редакцию правил подтверждают перед пилотом. Маскирование имени не является автоматическим разрешением на отправку оставшегося документа.',9.3,color=U,space=8)
    b.p('Источники и видео: '+link('R16')+' · '+link('R17')+' · '+link('R28'),9.2,markup=True)

    b.new('Атлас: каналы, диалог и оператор','Один контракт для нескольких каналов','atlas_dialogue')
    b.p('Сначала реализуй основной канал и проверь весь сценарий. Второй адаптер подтверждает переносимость. Три канала на схеме - варианты подключения, а не обязанность сделать три интерфейса одновременно.',10,space=13)
    y=b.y
    for x,t,body in zip(xs,['Telegram','Чат CRM','Web'],['update_id + webhook','Событие по контракту','SSE / WebSocket']):box(b,x,y,bw,60,t,body,P)
    yy=y-106
    for x in xs:arrow(b,x+75,y-60,x+75,yy)
    c=b.c;c.setFillColor(A);c.setStrokeColor(L);c.roundRect(M,yy-99,CW,99,6,fill=1,stroke=1)
    p=para('Адаптеры -> единое ядро диалога',13,True,T,align=1);_,ph=p.wrap(CW-24,100);p.drawOn(c,M+12,yy-12-ph)
    p=para('Проверенные tenant / пользователь / сессия<br/>Состояние, история и сводка, бюджет токенов, дедупликация входа<br/>Очередь, ограничения и явный статус для пользователя',10,align=1,markup=True);_,ph=p.wrap(CW-26,100);p.drawOn(c,M+13,yy-39-ph)
    zz=yy-145
    for x,t,body in zip(xs,['LLM + RAG','Инструменты','Оператор'],['Разрешённый контекст\nИсточники и ответ','Авторизация backend\nReview перед записью','История + черновик\nПередача и возврат']):
        arrow(b,x+75,yy-99,x+75,zz);box(b,x,zz,bw,79,t,body,P)
    b.y=zz-100;b.figures+=1
    b.section('Что проверять при повторе','Ключ входящего события включает область уникальности поставщика и канала. Повтор update не должен повторно запускать уже зарегистрированную бизнес-операцию. Для неизвестного результата внешней отправки остаётся отдельная политика и видимый статус.')
    b.section('Когда диалог успешен','Отдельно измеряй решение задачи пользователя, долю автоматизации и корректность передачи человеку. Правильная эскалация может быть требуемым результатом; её нельзя автоматически записывать в провал бота.')
    b.p('Проверяемые сценарии: смена темы, исчерпанный контекст, повтор события, обрыв потока, запрещённое действие, просьба позвать человека, возврат оператором.',9.5,space=10)
    reading(b,a,'15')
